def solve(g):
 w=99;S={r*w+c for r,t in enumerate(g)for c,v in enumerate(t)if v};q=[p for p in S if sum(p+d in S for d in(1,-1,w,-w))<2]
 while q:
  p=q.pop()
  if p in S:
   S-={p}
   for d in(1,-1,w,-w):
    n=p+d
    if(n in S)and(sum(n+k in S for k in(1,-1,w,-w))<2):q+=[n]
 return[[v+2*(r*w+c in S)for c,v in enumerate(t)]for r,t in enumerate(g)]
solve()
